            if (g[i][j] == 'R' && comp[id(i, j)] == -1) {
                comp[id(i, j)] = cid;
                q.push({i, j});
                while (!q.empty()) {
                    auto [x, y] = q.front(); q.pop();
                    for (int k = 0; k < 4; k++) {
                        int nx = x + dx[k], ny = y + dy[k];
                        if (0 <= nx && nx < n && 0 <= ny && ny < m && g[nx][ny] == 'R') {
                            int v = id(nx, ny);
                            if (comp[v] == -1) {
                                comp[v] = cid;
